              tunnel_status(directory, "unsupported")
              break
            }
            Retry(reason) => {
              failures += 1
              connected = false
              git_relay_status(directory, "unavailable")
              tunnel_status(directory, "checking")
              save_diagnostic(
                "relay-recovery",
                "failed",
                attempt=failures,
                error_type=reason,
                tunnel_directory=directory,
              )
              if failures >= 2 {
                break
              }
              continue
            }
          }
        }
