moonbit_sha256_linux_x64 = "24b93a5409d2a4fb8e3d1b84b473f27b63476cef4418094764df96cb26b03c09"
moonbit_sha256_linux_arm64 = "27551288b9552db1426d186403645bb40308a3f5e525054d0a2860283ae118bf"
moonbit_sha256_windows_x64 = "6e3ef6cb96aa5086d122183972687f79fc912f80652000907d96ee6ad967e3bf"

[tools]
zig = "0.17.0"
actionlint = "1.7.12"
hk = "1.55.0"
taplo = "0.10.0"
container = { version = "1.5.0", os = ["macos/arm64"] }
bun = "1.4.3"

[env]
HK_MISE = 1

[hooks]
postinstall = "hk install --mise"

[tool_config]
locked = true

[settings]
experimental = true

[deps.moonbit]
auto = true
sources = ["moon.mod", "mise.toml"]
outputs = [".mooncakes"]
run = "moon update && moon check --target native --dry-run --quiet"

[tasks.check]
description = "Check repository formatting, workflows and native types"
run = "hk check --all"

[tasks.fix]
description = "Format repository files"
run = "hk fix --all"

[tasks.test]
description = "Run unit and local boundary tests"
depends = ["check"]
run = [
  "moon build --target native --release --deny-warn",
  "moon test --target native --deny-warn",
  "bun test tests/release-build.test.ts tests/process.test.ts tests/e2e/diagnostics.test.ts",
]

[tasks.build]
description = "Build the standalone native executable"
run = "moon build --target native --release --deny-warn"

[tasks."cross:prepare"]
description = "Prepare source runtime and checksum-pinned Darwin header"
run = "bun scripts/prepare-cross.ts"

[tasks."release:build"]
description = "Cross build every standalone artifact for one SemVer release"
depends = ["cross:prepare"]
run = "bun scripts/release-build.ts"

[deps.tooling]
auto = true
sources = ["package.json", "bun.lock"]
outputs = ["node_modules/.installed"]
run = "bun install --frozen-lockfile && touch node_modules/.installed"

[tasks."test:e2e"]
description = "Run stable Orca/provider integration scenarios (explicit --provider required)"
depends = ["build"]
tools = { "github:devsy-org/devsy[matching=devsy-]" = "1.25.0-beta.3" }
run = "bun tests/e2e/main.ts"

[tasks."test:e2e:prepare-ci"]
description = "Prepare pinned runtimes and Electron libraries on the disposable Linux CI runner"
run = "bun tests/e2e/prepare-ci.ts"
env = { E2E_DOCKER_VERSION = "{{vars.e2e_docker_version}}", E2E_CONTAINERD_PACKAGE = "{{vars.e2e_containerd_package}}", E2E_BUILDX_PACKAGE = "{{vars.e2e_buildx_package}}", E2E_PODMAN_PACKAGE = "{{vars.e2e_podman_package}}" }
"}

